1	package main
2	
3	import (
4		"context"
5		"encoding/base64"
6		"fmt"
7		"os"
8		"os/exec"
9		"path/filepath"
10		"strconv"
11		"strings"
12	
13		"github.com/wailsapp/wails/v2/pkg/runtime"
14	
15		"paper-scan-processor/backend/drive"
16		"paper-scan-processor/backend/filetree"
17		"paper-scan-processor/backend/pdf"
18	)
19	
20	// App struct
21	type App struct {
22		ctx context.Context
23	}
24	
25	// NewApp creates a new App application struct
26	func NewApp() *App {
27		return &App{}
28	}
29	
30	// startup is called when the app starts. The context is saved
31	// so we can call the runtime methods
32	func (a *App) startup(ctx context.Context) {
33		a.ctx = ctx
34	}
35	
36	// OpenPDF shows a file-open dialog filtered to PDFs and returns the selected path.
37	// Returns an empty string if the user cancels.
38	func (a *App) OpenPDF() (string, error) {
39		path, err := runtime.OpenFileDialog(a.ctx, runtime.OpenDialogOptions{
40			Title: "Open PDF",
41			Filters: []runtime.FileFilter{
42				{DisplayName: "PDF Files (*.pdf)", Pattern: "*.pdf"},
43			},
44		})
45		return path, err
46	}
47	
48	// PageCount returns the number of pages in the PDF at path.
49	func (a *App) PageCount(path string) (int, error) {
50		return pdf.PageCount(path)
51	}
52	
53	// RenderPage renders a single page of the PDF at path as a PNG and returns it
54	// base64-encoded. widthPx controls the output width; height is scaled proportionally.
55	func (a *App) RenderPage(path string, pageNum int, widthPx int) (string, error) {
56		tmpDir, err := os.MkdirTemp("", "psp-render-*")
57		if err != nil {
58			return "", err
59		}
60		defer os.RemoveAll(tmpDir)
61	
62		outPrefix := filepath.Join(tmpDir, "page")
63		page := strconv.Itoa(pageNum)
64	
65		out, err := exec.Command(
66			"pdftoppm",
67			"-f", page,
68			"-l", page,
69			"-singlefile",
70			"-png",
71			"-scale-to-x", strconv.Itoa(widthPx),
72			"-scale-to-y", "-1",
73			path,
74			outPrefix,
75		).CombinedOutput()
76		if err != nil {
77			return "", fmt.Errorf("pdftoppm: %w\n%s", err, out)
78		}
79	
80		data, err := os.ReadFile(outPrefix + ".png")
81		if err != nil {
82			return "", err
83		}
84		return base64.StdEncoding.EncodeToString(data), nil
