// Depth-first flat list of every file under group — its own files first, then
// each subgroup recursively. Shared by the upload worker (which needs an
// ordered list of what to upload next), the modal's per-group rollup counts,
// and the "every file in this group is done" check, so all three agree on how
// nesting is walked instead of drifting apart across separate recursions.
export function flattenFiles(group: LocalFileGroup): LocalFile[] {
  return [...group.files, ...group.subgroups.flatMap(flattenFiles)]
}

