import { useState, useRef, useCallback } from 'react'
import { UploadToDrive } from '../../../wailsjs/go/main/App'

export type UploadStatus = 'idle' | 'queued' | 'uploading' | 'done' | 'error'

export interface UploadState {
  status: UploadStatus
  error?: string
}

// One file to upload: its local path, the resolved Drive folder to upload
// into, and the name to give it on Drive (empty falls back to the base name).
// Callers resolve folderId/name by walking the tree before starting a run.
export interface UploadTarget {
  path: string
  folderId: string
  name: string
}

export interface UploadQueueHandle {
  statuses: Map<string, UploadState>
  // A worker loop is actively draining the queue.
  running: boolean
  // Cancel-remaining has been requested for the current run.
  cancelRequested: boolean
  start: (targets: UploadTarget[]) => void
  retryAll: () => void
  retryFile: (path: string) => void
  cancelRemaining: () => void
  reset: () => void
}

// Tracks per-file upload status and drives a sequential (concurrency = 1)
// worker over a queue of targets. The status model is concurrency-agnostic:
// bumping to an N-way pool later is a change to the worker loop only.
export function useUploadQueue(): UploadQueueHandle {
  const [statuses, setStatuses] = useState<Map<string, UploadState>>(new Map())
  const [running, setRunning] = useState(false)
  const [cancelRequested, setCancelRequested] = useState(false)

  // Refs mirror the reactive state so the async worker loop always reads
  // current values without needing to be re-created on every render.
  const statusesRef = useRef(statuses)
  const targetsRef = useRef<Map<string, UploadTarget>>(new Map())
  const queueRef = useRef<string[]>([])
  const runningRef = useRef(false)
  const cancelRef = useRef(false)

  const commit = useCallback((next: Map<string, UploadState>) => {
    statusesRef.current = next
    setStatuses(next)
  }, [])

  const setStatus = useCallback((path: string, state: UploadState) => {
    const next = new Map(statusesRef.current)
    next.set(path, state)
    commit(next)
  }, [commit])

  const pump = useCallback(async () => {
    if (runningRef.current) return
    runningRef.current = true
    setRunning(true)
    try {
      while (!cancelRef.current && queueRef.current.length > 0) {
        const path = queueRef.current.shift()!
        const target = targetsRef.current.get(path)
        if (!target) continue
        setStatus(path, { status: 'uploading' })
        try {
          await UploadToDrive(target.path, target.folderId, target.name)
          setStatus(path, { status: 'done' })
        } catch (e) {
          setStatus(path, { status: 'error', error: String(e) })
        }
      }
    } finally {
      runningRef.current = false
      setRunning(false)
    }
  }, [setStatus])

  const enqueue = useCallback((paths: string[]) => {
    cancelRef.current = false
    setCancelRequested(false)
    const next = new Map(statusesRef.current)
    for (const p of paths) {
      if (!targetsRef.current.has(p)) continue
      if (!queueRef.current.includes(p)) queueRef.current.push(p)
      next.set(p, { status: 'queued' })
    }
    commit(next)
    void pump()
  }, [commit, pump])

  const start = useCallback((targets: UploadTarget[]) => {
    targetsRef.current = new Map(targets.map(t => [t.path, t]))
    enqueue(targets.map(t => t.path))
  }, [enqueue])

  const retryAll = useCallback(() => {
    const failed = [...statusesRef.current.entries()]
      .filter(([, s]) => s.status === 'error')
      .map(([p]) => p)
    enqueue(failed)
  }, [enqueue])

  const retryFile = useCallback((path: string) => {
    enqueue([path])
  }, [enqueue])

  const cancelRemaining = useCallback(() => {
    cancelRef.current = true
    setCancelRequested(true)
    // Drop not-yet-started files off the queue and back to idle so they don't
    // sit "queued" forever (which would keep the modal's Close disabled). The
    // in-flight file isn't on the queue, so it finishes normally.
    const pending = queueRef.current
    queueRef.current = []
    if (pending.length > 0) {
      const next = new Map(statusesRef.current)
      for (const p of pending) {
        if (next.get(p)?.status === 'queued') next.set(p, { status: 'idle' })
      }
      commit(next)
    }
  }, [commit])

  const reset = useCallback(() => {
    cancelRef.current = true
    queueRef.current = []
    targetsRef.current = new Map()
    setCancelRequested(false)
    commit(new Map())
  }, [commit])

  return { statuses, running, cancelRequested, start, retryAll, retryFile, cancelRemaining, reset }
}

