import { describe, it, expect, vi, beforeEach } from 'vitest'
import { act, renderHook, waitFor } from '@testing-library/react'
import { useUploadQueue, UploadTarget } from './useUploadQueue'
import { UploadToDrive } from '../../../wailsjs/go/main/App'

vi.mock('../../../wailsjs/go/main/App', () => ({
  UploadToDrive: vi.fn(),
}))

const mockUpload = vi.mocked(UploadToDrive)

// A promise plus its resolve/reject, to control when an upload "finishes".
function deferred<T>() {
  let resolve!: (v: T) => void
  let reject!: (e: unknown) => void
  const promise = new Promise<T>((res, rej) => { resolve = res; reject = rej })
  return { promise, resolve, reject }
}

function target(path: string, folderId = 'folder', name = ''): UploadTarget {
  return { path, folderId, name }
}

beforeEach(() => {
  mockUpload.mockReset()
})

describe('useUploadQueue', () => {
  it('starts with no statuses and not running', () => {
    const { result } = renderHook(() => useUploadQueue())
    expect(result.current.statuses.size).toBe(0)
    expect(result.current.running).toBe(false)
  })

  it('uploads targets sequentially and marks each done', async () => {
    mockUpload.mockResolvedValue('drive-id')
    const { result } = renderHook(() => useUploadQueue())

    act(() => { result.current.start([target('a'), target('b')]) })

    await waitFor(() => {
      expect(result.current.statuses.get('a')?.status).toBe('done')
      expect(result.current.statuses.get('b')?.status).toBe('done')
    })
    expect(result.current.running).toBe(false)
    expect(mockUpload).toHaveBeenCalledTimes(2)
    expect(mockUpload).toHaveBeenNthCalledWith(1, 'a', 'folder', '')
  })

  it('runs one file at a time, holding the rest queued', async () => {
    const first = deferred<string>()
    mockUpload.mockReturnValueOnce(first.promise).mockResolvedValue('id')
    const { result } = renderHook(() => useUploadQueue())

    act(() => { result.current.start([target('a'), target('b')]) })

    // While a is uploading, b waits queued and b's upload hasn't started.
    await waitFor(() => expect(result.current.statuses.get('a')?.status).toBe('uploading'))
    expect(result.current.statuses.get('b')?.status).toBe('queued')
    expect(mockUpload).toHaveBeenCalledTimes(1)

    await act(async () => { first.resolve('id') })
    await waitFor(() => expect(result.current.statuses.get('b')?.status).toBe('done'))
    expect(result.current.statuses.get('a')?.status).toBe('done')
  })

  it('captures the error message on failure', async () => {
    mockUpload.mockRejectedValue('boom')
    const { result } = renderHook(() => useUploadQueue())

    act(() => { result.current.start([target('a')]) })

    await waitFor(() => {
      const s = result.current.statuses.get('a')
      expect(s?.status).toBe('error')
      expect(s?.error).toContain('boom')
    })
  })

  it('retryFile re-queues just that file', async () => {
    mockUpload.mockRejectedValueOnce('boom').mockResolvedValue('id')
    const { result } = renderHook(() => useUploadQueue())

    act(() => { result.current.start([target('a')]) })
    await waitFor(() => expect(result.current.statuses.get('a')?.status).toBe('error'))

    act(() => { result.current.retryFile('a') })
    await waitFor(() => expect(result.current.statuses.get('a')?.status).toBe('done'))
    expect(mockUpload).toHaveBeenCalledTimes(2)
  })

  it('retryAll re-queues only the failed files', async () => {
    mockUpload
      .mockResolvedValueOnce('id')   // a done
      .mockRejectedValueOnce('boom') // b error
      .mockResolvedValue('id')       // b retry succeeds
    const { result } = renderHook(() => useUploadQueue())

    act(() => { result.current.start([target('a'), target('b')]) })
    await waitFor(() => expect(result.current.statuses.get('b')?.status).toBe('error'))

    mockUpload.mockClear()
    act(() => { result.current.retryAll() })
    await waitFor(() => expect(result.current.statuses.get('b')?.status).toBe('done'))
    // a was already done and must not be re-uploaded.
    expect(mockUpload).toHaveBeenCalledTimes(1)
    expect(mockUpload).toHaveBeenCalledWith('b', 'folder', '')
  })

  it('cancelRemaining reverts queued files to idle while the in-flight one finishes', async () => {
    const first = deferred<string>()
    mockUpload.mockReturnValueOnce(first.promise).mockResolvedValue('id')
    const { result } = renderHook(() => useUploadQueue())

    act(() => { result.current.start([target('a'), target('b')]) })
    await waitFor(() => expect(result.current.statuses.get('a')?.status).toBe('uploading'))

    act(() => { result.current.cancelRemaining() })
    expect(result.current.statuses.get('b')?.status).toBe('idle')
    expect(result.current.cancelRequested).toBe(true)

    await act(async () => { first.resolve('id') })
    await waitFor(() => expect(result.current.running).toBe(false))
    expect(result.current.statuses.get('a')?.status).toBe('done')
    // b was never uploaded.
    expect(mockUpload).toHaveBeenCalledTimes(1)
  })

  it('reset clears all status', async () => {
    mockUpload.mockResolvedValue('id')
    const { result } = renderHook(() => useUploadQueue())

    act(() => { result.current.start([target('a')]) })
    await waitFor(() => expect(result.current.statuses.get('a')?.status).toBe('done'))

    act(() => { result.current.reset() })
    expect(result.current.statuses.size).toBe(0)
  })
})

