import { useEffect, useState } from 'react'
import { UploadToDrive } from '../../../wailsjs/go/main/App'

export type UploadStatus = 'idle' | 'queued' | 'uploading' | 'done' | 'error'

export interface UploadState {
  status: UploadStatus
  error?: string
}

// One file to upload: its local path, the resolved Drive folder to upload
// into, and the name to give it on Drive (empty falls back to the base name).
// Callers resolve folderId/name by walking the tree before starting a run.
export interface UploadTarget {
  path: string
  folderId: string
  name: string
}

// statuses holds the current per-file status keyed by local path.
// targets remembers each file's locked-in destination/name so retries re-send
// to the same place.
// queue is the ordered list of paths waiting for the sequential worker;
// running guards against a second worker loop starting.
// generation is bumped on reset so an in-flight upload from a discarded run
// (e.g. a new root picked mid-upload) knows not to write its result back.
const statuses = new Map<string, UploadState>()
const targets = new Map<string, UploadTarget>()
let queue: string[] = []
let running = false
let cancelRequested = false
let generation = 0
const listeners = new Set<() => void>()

function notify() {
  for (const fn of listeners) fn()
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

// Re-renders the calling component whenever the queue changes.
export function useUploadQueueRender() {
  const [, setTick] = useState(0)
  useEffect(() => subscribe(() => setTick(t => t + 1)), [])
}

export function getStatus(path: string): UploadState | undefined {
  return statuses.get(path)
}

export function isRunning(): boolean {
  return running
}

export function isCancelRequested(): boolean {
  return cancelRequested
}

// Sequential (concurrency = 1) worker: uploads one queued file at a time in
// order. The status model is concurrency-agnostic, so an N-way pool later
// would be a change to this loop only.
async function pump() {
  if (running) return
  running = true
  notify()
  while (!cancelRequested && queue.length > 0) {
    const path = queue.shift()!
    const target = targets.get(path)
    if (!target) continue
    const gen = generation
    statuses.set(path, { status: 'uploading' })
    notify()
    let next: UploadState
    try {
      await UploadToDrive(target.path, target.folderId, target.name)
      next = { status: 'done' }
    } catch (e) {
      next = { status: 'error', error: String(e) }
    }
    // A reset during the upload discarded this run — don't write a stale
    // result back into the cleared state.
    if (gen !== generation) return
    statuses.set(path, next)
    notify()
  }
  running = false
  notify()
}

function enqueue(paths: string[]) {
  cancelRequested = false
  for (const p of paths) {
    if (!targets.has(p)) continue
    if (!queue.includes(p)) queue.push(p)
    statuses.set(p, { status: 'queued' })
  }
  notify()
  void pump()
}

// Starts a run over targets: records their locked-in destinations and queues
// them all.
export function start(newTargets: UploadTarget[]) {
  targets.clear()
  for (const t of newTargets) targets.set(t.path, t)
  enqueue(newTargets.map(t => t.path))
}

// Re-queues only the files that ended in error, leaving done files untouched.
export function retryAll() {
  const failed = [...statuses.entries()]
    .filter(([, s]) => s.status === 'error')
    .map(([p]) => p)
  enqueue(failed)
}

// Re-queues a single file (its Retry button) without touching the others.
export function retryFile(path: string) {
  enqueue([path])
}

// Stops starting new files. The in-flight upload isn't on the queue, so it
// finishes normally; not-yet-started files revert to idle so they don't sit
// "queued" forever (which would keep the modal's Close disabled).
export function cancelRemaining() {
  cancelRequested = true
  const pending = queue
  queue = []
  for (const p of pending) {
    if (statuses.get(p)?.status === 'queued') statuses.set(p, { status: 'idle' })
  }
  notify()
}

// Discards all queue state — used when a new root replaces the whole tree.
export function reset() {
  generation++
  queue = []
  targets.clear()
  statuses.clear()
  running = false
  cancelRequested = false
  notify()
}

